+/* Source contract for below-world travel and recovery health reporting. */
+
+#include <cstdlib>
+#include <fstream>
+#include <iostream>
+#include <iterator>
+#include <string>
+
+namespace
+{
+bool Has(std::string const& text, char const* needle, std::size_t from = 0)
+{
+    return text.find(needle, from) != std::string::npos;
+}
+
+int Fail(char const* what)
+{
+    std::cerr << what << "\n";
+    return EXIT_FAILURE;
+}
+}  // namespace
+
+int main()
+{
+    std::ifstream source("src/mod_orchestrator.cpp");
+    if (!source)
+        return Fail("cannot read src/mod_orchestrator.cpp");
+    std::string const text((std::istreambuf_iterator<char>(source)),
+                           std::istreambuf_iterator<char>());
+
+    std::size_t const catchUp = text.find("bool CatchUpToward(");
+    std::size_t const catchUpEnd = text.find("    // WHAT STANDS ON THE LINE", catchUp);
+    if (catchUp == std::string::npos || catchUpEnd == std::string::npos)
+        return Fail("cannot find CatchUpToward");
+    std::string const aim = text.substr(catchUp, catchUpEnd - catchUp);
+    if (!Has(aim, "MoveAimToShore(leader, ax, ay, az)"))
+        return Fail("catch-up aim must measure ground and replace the raw z");
+    if (!Has(aim, "AimShore::NoGround"))
+        return Fail("catch-up aim must refuse when ground cannot be measured");
+    if (!Has(text, "z = ground;"))
+        return Fail("catch-up aim must write the measured surface height");
+
+    if (!Has(text, "most recently '{}' at level {} \"\n                 \"in zone {} at map {} position"))
+        return Fail("death log must include the coordinates stored in orchestrator_death");
+
+    std::size_t const probe = text.find("static std::string ProbeState(Player* bot)");
+    std::size_t const probeEnd = text.find("static ", probe + 1);
+    if (probe == std::string::npos || probeEnd == std::string::npos)
+        return Fail("cannot find ProbeState");
+    std::string const health = text.substr(probe, probeEnd - probe);
+    if (!Has(health, "recoveries_per_hour"))
+        return Fail("health state must expose the recoveries-per-hour metric");
+    if (!Has(text, "OrchestratorDecisions::RecoveriesPerHour(times, now)"))
+        return Fail("health state must calculate recoveries over the last hour");
+
+    std::cout << "below-world travel and health observability are wired\n";
+    return EXIT_SUCCESS;
+}
diff --git a/tests/test_recoveries_per_hour.cpp b/tests/test_recoveries_per_hour.cpp
new file mode 100644
index 0000000..542ccec
--- /dev/null
+++ b/tests/test_recoveries_per_hour.cpp
@@ -0,0 +1,70 @@
+/*
+ * Recoveries per hour — a health metric.
+ *
+ * A recovery that fires fifteen times an hour is an alarm, not a fix, and the
+ * page needs a count it can show. This pins the pure counting rule: how many
+ * remedy applications fall in the half-open interval (now - window, now].
+ *
+ * Compiled against src/orchestrator_decisions.cpp and nothing else.
+ */
+
+#include "orchestrator_decisions.h"
+
+#include <cstdio>
+#include <vector>
+
+using OrchestratorDecisions::RecoveriesPerHour;
+
+namespace
+{
+
+int failures = 0;
+
+void Check(char const* what, std::size_t got, std::size_t want)
+{
+    if (got == want)
+        return;
+    std::printf("FAIL %s: got %zu, wanted %zu\n", what, got, want);
+    ++failures;
+}
+
+}  // namespace
+
+int main()
+{
+    time_t const now = 100000;
+    time_t const hour = 3600;
+
+    // Remedies oldest first. One is exactly an hour old (excluded), one is
+    // just inside the window, one is right now.
+    std::vector<time_t> times = {now - hour - 1, now - hour, now - hour + 1, now};
+
+    Check("empty history", RecoveriesPerHour({}, now, hour), 0u);
+    Check("a zero window counts nothing", RecoveriesPerHour(times, now, 0), 0u);
+    Check("a negative window counts nothing", RecoveriesPerHour(times, now, -1), 0u);
+
+    // Exactly one hour old is outside the half-open interval.
+    Check("one hour old is excluded",
+          RecoveriesPerHour({now - hour}, now, hour), 0u);
+    // One second past the hour is inside.
+    Check("one second inside the hour is counted",
+          RecoveriesPerHour({now - hour + 1}, now, hour), 1u);
+    Check("four remedies, one at the boundary and one now",
+          RecoveriesPerHour(times, now, hour), 2u);
+
+    // A shorter window excludes the one just inside the hour.
+    Check("a ten-minute window keeps only the one now",
+          RecoveriesPerHour(times, now, 600), 1u);
+
+    // The default window is one hour.
+    Check("default window is one hour",
+          RecoveriesPerHour(times, now), 2u);
+
+    if (failures)
+    {
+        std::printf("%d failure(s)\n", failures);
+        return 1;
+    }
+    std::printf("recoveries per hour: ok\n");
+    return 0;
+}

