+#include "b64.h"
+
+/* Writes 4 output chars per 3 input bytes. out must hold 4*((len+2)/3)+1. */
+void base64_encode(const unsigned char *in, size_t len, char *out)
+{
+    static const char tbl[] =
+        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    size_t i, o = 0;
+    for (i = 0; i + 2 < len; i += 3) {
+        out[o++] = tbl[in[i] >> 2];
+        out[o++] = tbl[((in[i] & 0x03) << 4) | (in[i+1] >> 4)];
+        out[o++] = tbl[((in[i+1] & 0x0F) << 2) | (in[i+2] >> 6)];
+        out[o++] = tbl[in[i+2] & 0x3F];
+    }
+    if (i < len) {
+        out[o++] = tbl[in[i] >> 2];
+        if (i + 1 < len) {
+            out[o++] = tbl[((in[i] & 0x03) << 4) | (in[i+1] >> 4)];
+            out[o++] = tbl[(in[i+1] & 0x0F) << 2];
+        } else {
+            out[o++] = tbl[(in[i] & 0x03) << 4];
+            out[o++] = '=';
+        }
+        out[o++] = '=';
+    }
+    out[o] = '\0';
+}
