diff --git a/tests/host/test_b64.c b/tests/host/test_b64.c
new file mode 100644
index 0000000..dcc6010
--- /dev/null
+++ b/tests/host/test_b64.c
@@ -0,0 +1,136 @@
+/*
+ * Host test: a binary fatal survives base64 byte for byte.
+ *
+ * AFE2 blobs are about 1104 bytes and mostly NUL. They ship base64 encoded, so
+ * anything that drops or alters a byte would corrupt the only register state
+ * a panic leaves behind. The decoder here is an independent reference.
+ */
+
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+
+#include "../../common/b64.h"
+
+static int g_checks;
+static int g_failures;
+
+#define CHECK(cond, ...)                                                      \
+    do {                                                                      \
+        g_checks++;                                                           \
+        if (!(cond)) {                                                        \
+            g_failures++;                                                     \
+            printf("  FAIL %s:%d: ", __func__, __LINE__);                     \
+            printf(__VA_ARGS__);                                              \
+            printf("\n");                                                     \
+        }                                                                     \
+    } while (0)
+
+static int b64_val(char c)
+{
+    if (c >= 'A' && c <= 'Z') return c - 'A';
+    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
+    if (c >= '0' && c <= '9') return c - '0' + 52;
+    if (c == '+') return 62;
+    if (c == '/') return 63;
+    return -1;
+}
+
+/* Reference decoder. Returns decoded length, or -1 on malformed input. */
+static long ref_decode(const char *in, unsigned char *out)
+{
+    size_t n = strlen(in), o = 0, i;
+    if (n % 4 != 0)
+        return -1;
+    for (i = 0; i < n; i += 4) {
+        int v0 = b64_val(in[i]), v1 = b64_val(in[i + 1]);
+        int pad2 = (in[i + 2] == '='), pad3 = (in[i + 3] == '=');
+        int v2 = pad2 ? 0 : b64_val(in[i + 2]);
+        int v3 = pad3 ? 0 : b64_val(in[i + 3]);
+        unsigned int w;
+        if (v0 < 0 || v1 < 0 || v2 < 0 || v3 < 0)
+            return -1;
+        if ((pad2 && !pad3) || ((pad2 || pad3) && i + 4 != n))
+            return -1;
+        w = ((unsigned int)v0 << 18) | ((unsigned int)v1 << 12) |
+            ((unsigned int)v2 << 6) | (unsigned int)v3;
+        out[o++] = (unsigned char)(w >> 16);
+        if (!pad2)
+            out[o++] = (unsigned char)(w >> 8);
+        if (!pad3)
+            out[o++] = (unsigned char)w;
+    }
+    return (long)o;
+}
+
+static void roundtrip(const unsigned char *buf, size_t len)
+{
+    size_t enc_cap = 4 * ((len + 2) / 3) + 1;
+    char *enc = malloc(enc_cap);
+    unsigned char *dec = malloc(len + 3);
+    long n;
+
+    base64_encode(buf, len, enc);
+    CHECK(strlen(enc) == enc_cap - 1, "len %zu: encoded %zu chars, want %zu",
+          len, strlen(enc), enc_cap - 1);
+    n = ref_decode(enc, dec);
+    CHECK(n == (long)len, "len %zu: decoded %ld bytes", len, n);
+    CHECK(n == (long)len && (len == 0 || memcmp(buf, dec, len) == 0),
+          "len %zu: bytes differ after round trip", len);
+    free(enc);
+    free(dec);
+}
+
+static void test_afe2_blob(void)
+{
+    unsigned char blob[1104];
+    size_t i, zeros = 0;
+
+    memset(blob, 0, sizeof(blob));
+    memcpy(blob, "AFE2", 4);
+    blob[4] = 0xFE; blob[5] = 0x0F;               /* error desc 0xFFE */
+    blob[8] = 0x34;                               /* program id 0x...34 */
+    blob[11] = 0x00;
+    for (i = 0x40; i < sizeof(blob); i += 37)     /* sparse register-ish data */
+        blob[i] = (unsigned char)(i * 7 + 0x80);
+    blob[1103] = 0xFF;
+    for (i = 0; i < sizeof(blob); i++)
+        zeros += (blob[i] == 0);
+    CHECK(zeros > 800, "fixture should be mostly NUL, got %zu", zeros);
+    roundtrip(blob, sizeof(blob));
+}
+
+static void test_lengths_mod3(void)
+{
+    unsigned char buf[1110];
+    size_t len, i;
+
+    for (i = 0; i < sizeof(buf); i++)
+        buf[i] = (unsigned char)(i % 5 == 0 ? 0 : i * 31 + 7);
+    for (len = 0; len <= 12; len++)               /* 0,1,2 mod 3, repeatedly */
+        roundtrip(buf, len);
+    for (len = 1101; len <= 1110; len++)
+        roundtrip(buf, len);
+}
+
+static void test_known_vectors(void)
+{
+    char out[16];
+    base64_encode((const unsigned char *)"", 0, out);
+    CHECK(strcmp(out, "") == 0, "empty: '%s'", out);
+    base64_encode((const unsigned char *)"f", 1, out);
+    CHECK(strcmp(out, "Zg==") == 0, "f: '%s'", out);
+    base64_encode((const unsigned char *)"fo", 2, out);
+    CHECK(strcmp(out, "Zm8=") == 0, "fo: '%s'", out);
+    base64_encode((const unsigned char *)"foo", 3, out);
+    CHECK(strcmp(out, "Zm9v") == 0, "foo: '%s'", out);
+}
+
+int main(void)
+{
+    test_known_vectors();
+    test_afe2_blob();
+    test_lengths_mod3();
+    printf("%d checks, %d failures\n", g_checks, g_failures);
+    return g_failures ? 1 : 0;
+}

